source("common.R")
library(DBI)
con <- dbConnect(spark_driver(), URL)
spark_config(con, spark.sql.session.timeZone = "UTC")
cat("## ${} substitution\n")
df <- data.frame(s = c("price ${amount}", "${spark.app.name}", "${env:HOME}", "${system:java.version}", "$ {x}", "$${x}", "{x}"), stringsAsFactors = FALSE)
t({dbWriteTable(con, "zzsub", df, temporary = TRUE, overwrite = TRUE); r <- dbReadTable(con, "zzsub"); print(cbind(df, out = r$s, same = df$s == r$s)); 1}, FALSE)
t(dbGetQuery(con, paste("SELECT", dbQuoteString(con, "${spark.app.name}"), "AS x")))
t(dbGetQuery(con, "SELECT '\\u0024{spark.app.name}' AS x"))
cat("## negative zero / decimal field.types\n")
d <- data.frame(x = c(0.1, 0.3, 1/3, -0.0, 2.675))
t({dbWriteTable(con, "zzdec", d, temporary = TRUE, overwrite = TRUE, field.types = c(x = "DECIMAL(38,20)")); dbGetQuery(con, "SELECT CAST(x AS STRING) AS s FROM zzdec")})
t({dbWriteTable(con, "zzdec2", d, temporary = TRUE, overwrite = TRUE); dbGetQuery(con, "SELECT CAST(CAST(x AS DECIMAL(38,20)) AS STRING) AS s, 1/x AS inv FROM zzdec2")})
t({dbWriteTable(con, "zzflt", data.frame(x = c(0.1, 16777217, 1e39)), temporary = TRUE, overwrite = TRUE, field.types = c(x = "FLOAT")); dbGetQuery(con, "SELECT x, CAST(x AS STRING) s FROM zzflt")})
t({dbWriteTable(con, "zzint", data.frame(x = c(1.5, 2.5, -1.5, NaN, 3e9)), temporary = TRUE, overwrite = TRUE, field.types = c(x = "INT")); dbGetQuery(con, "SELECT x FROM zzint")})
cat("## date extremes\n")
dd <- structure(c(2932897, -719893, -719528 - 366, 2932896), class = "Date"); print(format(dd, "%Y-%m-%d"))
t({dbWriteTable(con, "zzdate", data.frame(d = dd), temporary = TRUE, overwrite = TRUE); r <- dbGetQuery(con, "SELECT CAST(d AS STRING) s, datediff(d, DATE'1970-01-01') n FROM zzdate"); cbind(r, expect = as.numeric(dd))})
cat("## field.types edge\n")
d2 <- data.frame(a = 1:2, b = c("x", "y"))
t(zuspark:::spark_values_select(d2, c("INT", "STRING")))
t(zuspark:::spark_values_select(d2, c(a = "BIGINT", zz = "INT")))
t(zuspark:::spark_values_select(d2, list(a = "BIGINT")))
t(zuspark:::spark_values_select(d2, c(a = "BIGINT", a = "INT")))
t(zuspark:::spark_values_select(d2, c(b = NA)))
t(zuspark:::spark_values_select(data.frame()))
t(zuspark:::spark_values_select(d2[0, ]))
t(zuspark:::spark_values_select(data.frame(sep = "a", collapse = "b")))
dup <- data.frame(a = 1L, a = "x", check.names = FALSE); t(zuspark:::spark_values_select(dup)); t(zuspark:::spark_values_select(dup, c(a = "BIGINT")))
nested <- data.frame(a = 1:2); nested$m <- matrix(1:4, 2); t(zuspark:::spark_values_select(nested))
nested2 <- data.frame(a = 1:2); nested2$d <- data.frame(p = 1:2, q = 3:4); t(zuspark:::spark_values_select(nested2))
cat("## write flows\n")
t(dbWriteTable(con, "zzw", d2)); t(dbWriteTable(con, "zzw", d2)); t(dbWriteTable(con, "zzw", d2, append = TRUE)); t(dbGetQuery(con, "SELECT count(*) n FROM zzw"))
t(dbWriteTable(con, "zzw", d2, overwrite = TRUE, append = TRUE)); t(dbWriteTable(con, "zzw", d2[2:1, 2:1], append = TRUE)); t(dbGetQuery(con, "SELECT * FROM zzw ORDER BY a"))
t(dbAppendTable(con, "zzw", data.frame(b = "only-b"))); t(dbAppendTable(con, "zzw", data.frame(a = 9L, zz = 1L))); t(dbAppendTable(con, "zzw", d2[0, ])); t(dbAppendTable(con, "zzw", d2, row.names = TRUE))
t(dbAppendTable(con, "zzw", data.frame(a = c(1.7, 2.5), b = c(1, 2)))); t(dbGetQuery(con, "SELECT * FROM zzw ORDER BY a, b"))
t(dbWriteTable(con, "zzw", data.frame(z = 1.5), overwrite = TRUE)); t(dbGetQuery(con, "SELECT * FROM zzw"))
t(dbWriteTable(con, "zzw", d2, temporary = TRUE)); t(dbWriteTable(con, "zzw", d2, temporary = TRUE, overwrite = TRUE)); t(dbGetQuery(con, "SELECT * FROM zzw"));
t(dbRemoveTable(con, "zzw")); t(dbGetQuery(con, "SELECT * FROM zzw")); t(dbRemoveTable(con, "zzw")); t(dbExistsTable(con, "zzw")); t(dbRemoveTable(con, "zzw")); t(dbRemoveTable(con, "zzw", fail_if_missing = FALSE))
t(dbWriteTable(con, "zztv", d2, temporary = TRUE)); t(dbWriteTable(con, "zztv", d2, overwrite = TRUE)); t(dbGetQuery(con, "SHOW TABLES")); t(dbRemoveTable(con, "zztv"));  t(dbRemoveTable(con, "zztv", fail_if_missing = FALSE))
t(dbWriteTable(con, "zzrn", data.frame(x = 1:2, row.names = c("r1", "r2")), temporary = TRUE, row.names = TRUE)); t(dbReadTable(con, "zzrn")); t(dbReadTable(con, "zzrn", row.names = TRUE))
t(dbWriteTable(con, Id("default", "zzid"), d2)); t(dbExistsTable(con, Id("default", "zzid"))); t(dbExistsTable(con, "default.zzid")); t(dbExistsTable(con, SQL("default.zzid"))); t(dbExistsTable(con, Id("nodb", "zzid"))); t(dbExistsTable(con, Id("nocat", "nodb", "zzid"))); t(dbListFields(con, Id("default", "zzid"))); t(dbRemoveTable(con, Id("default", "zzid")))
t(dbExistsTable(con, c("a", "b"))); t(dbExistsTable(con, NA_character_)); t(dbExistsTable(con, ""))
t(dbWriteTable(con, "zzf", data.frame(f = factor(c("b", "a", NA)), stringsAsFactors = TRUE), temporary = TRUE)); t(dbReadTable(con, "zzf"))
options(zuspark.write_warn_rows = 2); t(dbWriteTable(con, "zzwarn", data.frame(x = 1:3), temporary = TRUE)); options(zuspark.write_warn_rows = NULL)
cat("## fetch n\n")
res <- dbSendQuery(con, "SELECT id FROM range(10)")
t(dbGetRowCount(res)); t(dbHasCompleted(res)); t(dbColumnInfo(res)); t(dbGetStatement(res)); t(dbGetRowsAffected(res))
for (n in list(0, 3, 2L, 2.5, -2, NA, "1", TRUE, c(1, 2), NULL, -1L, 1e10)) { cat("n =", deparse(n), ": "); r <- t(dbFetch(res, n), FALSE); if (!inherits(r, "err")) cat(nrow(r), "rows; count", dbGetRowCount(res), "completed", dbHasCompleted(res), "\n") }
t(dbFetch(res)); t(dbFetch(res, Inf)); t(dbClearResult(res)); t(dbClearResult(res)); t(dbFetch(res)); t(dbIsValid(res)); t(dbGetRowCount(res))
res <- dbSendQuery(con, "SELECT id FROM range(5)"); t(nrow(dbFetch(res, Inf))); t(dbGetRowCount(res)); dbClearResult(res)
res <- dbSendQuery(con, "SHOW DATABASES"); t(dbHasCompleted(res)); t(dbColumnInfo(res)); t(dbFetch(res, 0)); t(dbFetch(res)); t(dbHasCompleted(res)); dbClearResult(res)
res <- dbSendStatement(con, "CREATE OR REPLACE TEMPORARY VIEW zzs AS SELECT 1 a"); t(dbGetRowsAffected(res)); t(dbHasCompleted(res)); t(dbFetch(res)); t(dbColumnInfo(res)); dbClearResult(res)
res <- dbSendQuery(con, "SELECT CAST(1 AS DECIMAL(5,2)) d, 1L b, array(1) a, INTERVAL '1' DAY i"); t(dbColumnInfo(res)); t(dbFetch(res)); t(dbHasCompleted(res)); dbClearResult(res)
res <- dbSendQuery(con, "SELECT CAST(1 AS DECIMAL(5,2)) d WHERE 1=0"); t(dbFetch(res)); dbClearResult(res)
t(dbGetQuery(con, "SELECT id FROM range(10)", n = 3)); t(dbGetQuery(con, "SELECT 1L AS b", lossy = "character")); t(dbGetQuery(con, "SELECT ? AS b", params = list(1))); t(dbGetQuery(con, "SELECT 1 AS b", params = list()))
t(dbExecute(con, "SELECT 1")); t(dbExecute(con, c("SELECT 1", "SELECT 2"))); t(dbGetQuery(con, SQL("SELECT 1 AS sql")))
r1 <- dbSendQuery(con, "SELECT 1 a"); r2 <- t(dbSendQuery(con, "SELECT 2 a")); t(dbFetch(r1)); t(dbFetch(r2)); dbClearResult(r2)
cat("## info\n")
t(dbGetInfo(con)); t(dbGetInfo(spark_driver())); print(con); t(dbIsValid(con))
t(dbBegin(con)); t(dbWithTransaction(con, 1))
t(dbConnect(spark_driver(), URL, user = "x")); t(dbConnect(spark_driver(), con = con@con, token = "ignored")); t(dbConnect(spark_driver(), con = con)); t(dbConnect(spark_driver(), con = 5))
t(dbDisconnect(con)); t(dbDisconnect(con)); t(dbIsValid(con)); t(dbGetInfo(con)); t(dbGetQuery(con, "select 1")); t(dbListTables(con))
